{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.dweekly/quicken-mac-mcp",
  "description": "Read-only access to Quicken For Mac financial data: transactions, spending, and portfolios.",
  "repository": {
    "url": "https://github.com/dweekly/quicken-mac-mcp",
    "source": "github"
  },
  "version": "1.5.0",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "quicken-mac-mcp",
      "version": "1.5.0",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Path to Quicken database file (auto-detected if not set)",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "QUICKEN_DB_PATH"
        }
      ]
    }
  ]
}
